-- Corregir alimento a pedido de la PO
UPDATE alimentos
SET nombre = 'Leche de almendras',
    categoria = 'Leche y postres de leche'
WHERE nombre = 'Alimento a base de almendras (leche de almendras)';

-- Corregir criterio de celiacos
UPDATE criterios
SET flag_objetivo = 'no_apto_celiaco'
WHERE descripcion = 'Que el paciente no consuma alimentos no aptos para celíacos';

-- Agregar columna no_apto_celiacos
ALTER TABLE alimentos
ADD COLUMN no_apto_celiaco BOOLEAN NOT NULL DEFAULT FALSE;

-- Establecer alimentos no aptos para celiacos
UPDATE alimentos
SET no_apto_celiaco = TRUE
WHERE id IN (160,161,162,192,253,260,261,268,269,270,
        271,305,358,359,376,384,385,386,387,388);

-- Agregar criterios faltantes en patologías
INSERT INTO patologias_criterios VALUES (7,12),(9,12);

